#include <bits/stdc++.h>
using namespace std; const long long P=1000000007;
long long pw(long long a,long long k){long long b=1;for(;k;k>>=1,a=a*a%P)if(k&1)b=b*a%P;return b;}
vector<long long> bm(vector<long long>s){vector<long long>C{1},B{1};int L=0,m=1;long long b=1;for(int n=0;n<(int)s.size();n++){long long d=s[n];for(int i=1;i<=L;i++)d=(d+C[i]*s[n-i])%P;if(!d){m++;continue;}auto T=C;long long c=d*pw(b,P-2)%P;if(C.size()<B.size()+m)C.resize(B.size()+m);for(int i=0;i<(int)B.size();i++)C[i+m]=(C[i+m]-c*B[i]%P+P)%P;if(2*L<=n){L=n+1-L;B=T;b=d;m=1;}else m++;}return C;}
vector<long long> remd(vector<long long>a,vector<long long>b){while(a.size()>=b.size()){long long c=a.back()*pw(b.back(),P-2)%P;int k=a.size()-b.size();for(int j=0;j<(int)b.size();j++)a[j+k]=(a[j+k]-c*b[j]%P+P)%P;while(a.size()&&a.back()==0)a.pop_back();}return a;}
vector<long long> gcdp(vector<long long>a,vector<long long>b){while(b.size()){auto r=remd(a,b);a=b;b=r;}return a;}
vector<long long> der(vector<long long>a){vector<long long>b;for(int i=1;i<(int)a.size();i++)b.push_back(a[i]*i%P);while(b.size()&&!b.back())b.pop_back();return b;}
int main(int argc,char**argv){int n=atoi(argv[1]),steps=atoi(argv[2]);int full=(1<<n)-1;vector<int> masks;for(int x=0;x<=full;x++)if(!(x&(x<<1))&&!((x&1)&&(x&(1<<(n-1)))))masks.push_back(x);auto rot=[&](int x){return ((x<<1)&full)|(x>>(n-1));};auto canon=[&](int x){int y=0;for(int i=0;i<n;i++)if(x>>i&1)y|=1<<(n-1-i);int z=min(x,y);for(int i=1;i<n;i++){x=rot(x);y=rot(y);z=min(z,min(x,y));}return z;};map<int,vector<int>>orbs;for(int x:masks)orbs[canon(x)].push_back(x);vector<int> reps,sz,sg;vector<vector<int>> mem;for(auto &[r,v]:orbs){reps.push_back(r);sz.push_back(v.size());sg.push_back(__builtin_popcount((unsigned)r)%2?-1:1);mem.push_back(v);}int N=reps.size();cerr<<"n "<<n<<" masks "<<masks.size()<<" orbits "<<N<<endl;vector<vector<pair<int,int>>>A(N);for(int i=0;i<N;i++)for(int j=0;j<N;j++){int c=0;for(int x:mem[j])c+=!(x&reps[i]);if(c)A[i].push_back({j,c});}vector<long long>v(N),w(N),s;v[0]=1;for(int k=0;k<=steps;k++){long long a=0;for(int i=0;i<N;i++)a=(a+sz[i]*v[i])%P;s.push_back(a);for(int i=0;i<N;i++){long long z=0;for(auto [j,c]:A[i])z+=c*v[j];z%=P;w[i]=sg[i]>0?z:(P-z)%P;}v.swap(w);}auto C=bm(s);auto G=gcdp(C,der(C));auto H=gcdp(G,der(G));cout<<"{\"n\":"<<n<<",\"steps\":"<<steps<<",\"prime\":"<<P<<",\"row_states\":"<<masks.size()<<",\"dihedral_orbits\":"<<N<<",\"BM_degree\":"<<C.size()-1<<",\"gcd_derivative_degree\":"<<(int)G.size()-1<<",\"triple_root_test_degree\":"<<(int)H.size()-1<<",\"C\":[";for(int i=0;i<C.size();i++)cout<<(i?",":"")<<C[i];cout<<"],\"sequence\":[";for(int i=0;i<s.size();i++)cout<<(i?",":"")<<s[i];cout<<"]}"<<endl;}
